import json, re

with open("/home/ubuntu/.claude-account-5/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-10-projects-provenance-weight-training/a4549da2-98bd-42c1-869e-15628e8757c5/tool-results/mcp-agent-ml-research-read_registry-1778911514420.txt") as f:
    outer = json.load(f)

data = json.loads(outer["result"])
exps = data["data"]["experiments"]

# Check what eval_loss variants exist
for field in ["eval_loss", "eval_loss_holdout"]:
    found_in = {}
    def find_in_dict(d, key, path=""):
        results = []
        if isinstance(d, dict):
            for k, v in d.items():
                if k == key:
                    results.append(f"{path}.{k}" if path else k)
                results.extend(find_in_dict(v, key, f"{path}.{k}" if path else k))
        return results
    for eid, exp in exps.items():
        paths = find_in_dict(exp, field)
        for p in paths:
            found_in.setdefault(p, []).append(eid)
    print(f"\n--- {field} ---")
    for path, eids in found_in.items():
        print(f"  {path}: {len(eids)} exps")

# Now, for experiments that don't have explicit weighting_method, let me infer from command or exp_id
print("\n\n=== Inferring weighting_method from exp_id / command ===")
for eid, exp in exps.items():
    # Try to find weighting_method
    wm = None
    wm = exp.get("spec", {}).get("weighting_method") or exp.get("metrics", {}).get("weighting_method")
    if not wm:
        # Try to parse from command
        cmd = exp.get("spec", {}).get("command", "") or exp.get("reproduce", {}).get("command", "")
        m = re.search(r'--weighting_method\s+(\S+)', cmd)
        if m:
            wm = m.group(1)
    if not wm:
        # Infer from exp_id
        if "uniform" in eid:
            wm = "uniform(inferred)"
        elif "adaptive" in eid:
            wm = "adaptive(inferred)"
        elif "ess_only" in eid:
            wm = "ess_only(inferred)"
        elif "grid" in eid:
            wm = "grid(inferred)"
        elif "detect_remove" in eid:
            wm = "detect_remove(inferred)"
        elif "threshold" in eid:
            wm = "threshold(inferred)"
        else:
            wm = "UNKNOWN"
    print(f"  {eid}: {wm}")
PYEOF
